 * Base Canvas2D node-radius band in CSS px. `seedField` rolls each node's radius in
 * `[NODE_R_MIN, NODE_R_MIN + NODE_R_SPREAD)`.
 */
export const NODE_R_MIN = 1.6;
export const NODE_R_SPREAD = 1.6;

