        arm: lifecycle.arm,
        presize: lifecycle.presize,
        suspend: lifecycle.suspend,
        resume: lifecycle.resume,
        wake: lifecycle.wake,
        renderAt: lifecycle.renderAt,
        dispose: lifecycle.dispose,
