            webgl2?.renderAt(t);
        },
        dispose: () => {
            disposed = true;
            webgpu?.dispose();
            webgl2?.dispose();
            webgpu = null;
            webgl2 = null;
        },
        get reducedMotion() {
            return (webgpu ?? webgl2)?.reducedMotion ?? false;
