    return {
        get backend() {
            return backend;
        },
        armAsync,
        arm,
        presize,
        suspend: (reason) => {
            webgpu?.suspend(reason);
            webgl2?.suspend(reason);
        },
        resume: (reason) => {
            webgpu?.resume(reason);
            webgl2?.resume(reason);
        },
        wake: () => {
            webgpu?.wake();
            webgl2?.wake();
        },
        renderAt: (t) => {
            webgpu?.renderAt(t);
            webgl2?.renderAt(t);
        },
        dispose: () => {
            disposed = true;
            webgpu?.dispose();
            webgl2?.dispose();
            webgpu = null;
            webgl2 = null;
